"""Write LaTeX numerical macros and tables directly from the final summaries."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]


def main():
    s=json.loads((ROOT/'data/final/summary.json').read_text())
    out=ROOT/'tables/final'; out.mkdir(parents=True,exist_ok=True)
    macros={}
    def pct(value): return f'{100*value:.1f}'.replace('.',',')+r'\%'
    for name,run in (('Bracket','bracket_validation'),('IndentOriginal','indent_validation'),('IndentShift','indent_boundary_validation')):
        if run not in s: continue
        r=s[run]
        for suffix,key in (('PairAccuracy','pair_accuracy'),('BroadAccuracy','candidate_accuracy'),('FullAccuracy','full_accuracy')):
            macros[name+suffix]=pct(r['behavior'][key]['estimate'])
        for suffix,key in (('Damage','set_task/damage'),('Restoration','set_task/restore'),
                           ('Sufficiency','keep_task_mlps1/forward')):
            macros[name+suffix]=pct(r['validation']['all_eligible']['effects'][key]['estimate'])
    for name,run in (('NaturalOriginal','behavior_run'),('NaturalShift','boundary_run')):
        macros[name+'Accuracy']=pct(s[run]['natural']['candidate_accuracy']['estimate'])
        macros[name+'FullAccuracy']=pct(s[run]['natural']['full_accuracy']['estimate'])
    for name,run in (('Bracket','curve_bracket'),('Indent','curve_indent')):
        if run not in s: continue
        effects=s[run]['curves']['all']
        first=next((n for n in (4,8,16,32,64,128,384)
                    if all(effects[f'ranked/{n}/{direction}']['estimate']>=.8 for direction in ('forward','reverse'))),None)
        macros[name+'CurveThreshold']=str(first) if first is not None else 'não atingido'
    (out/'numbers.tex').write_text('\n'.join(r'\newcommand{\'+k+'}{'+v+'}' for k,v in macros.items())+'\n')
    labels=['L14H10','L15H15','L18H13','L18H14','L15H3','L14H0','L15H0','L18H0']
    lines=[r'\begin{tabular}{lrrr}',r'\toprule',r'Head & Delimitadores & Indentação original & Fronteira deslocada \\',r'\midrule']
    for h in labels:
        cols=[]
        for run in ('bracket_validation','indent_validation','indent_boundary_validation'):
            if run in s:
                v=s[run]['validation']['all_eligible']['effects'][h+'/resample/damage']
                cols.append(f"{v['estimate']:.3f}".replace('.',','))
            else: cols.append('--')
        lines.append(h+' & '+' & '.join(cols)+r' \\')
    lines.extend([r'\bottomrule',r'\end{tabular}'])
    (out/'heads.tex').write_text('\n'.join(lines)+'\n')
    curves=[r'\begin{tabular}{lrrrr}',r'\toprule',r'Heads & Delim. limpa & Delim. reversa & Indent. limpa & Indent. reversa \\',r'\midrule']
    for n in (0,4,8,16,32,64,128,384):
        values=[]
        for run in ('curve_bracket','curve_indent'):
            for direction in ('forward','reverse'):
                values.append(f"{s[run]['curves']['all'][f'ranked/{n}/{direction}']['estimate']:.3f}".replace('.',',') if run in s else '--')
        curves.append(str(n)+' & '+' & '.join(values)+r' \\')
    curves += [r'\bottomrule',r'\end{tabular}']
    (out/'curves.tex').write_text('\n'.join(curves)+'\n')
    print('Wrote final tables and numerical macros.')


if __name__=='__main__':main()

